  const violations = validateStaticExportAudit(audit);
  console.log(JSON.stringify({
    validation: {
      status: violations.length === 0 ? "PASS" : "FAIL",
      violations,
    },
    ...audit,
  }, null, 2));
  if (violations.length > 0) process.exitCode = 1;
}

