    .querySelectorAll("title")
    .map((element) => normalizeText(element.textContent));
  const h1 = document
    .querySelectorAll("h1")
    .map((element) => normalizeText(element.textContent));
  const robots = extractRobots(document);

  return {
    pathname,
    htmlFile,
    canonical: canonicals[0] ?? null,
    canonicalCount: canonicals.length,
