components/layout/english/EnglishDesign..before:
/* Every rule is scoped to the English root. Do not move these into globals.css. */
.root {
  --en-link: color-mix(in srgb, var(--accent) 55%, var(--foreground));
  --en-copy: #d1d5db;
  --en-soft: #a1a1aa;
}

.root :global(:is(a, button, select, [tabindex]):focus-visible) {
  outline: 2px solid var(--en-link);
  outline-offset: 5px;
}
.root :global(a) { text-underline-offset: 4px; }
.root :global(.en-nav) {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--background) 84%, transparent);
  backdrop-filter: blur(16px);
}
.root :global(.en-nav-inner) {
  max-width: 1120px;
  margin: auto;
  min-height: 64px;
  padding: 8px 24px;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 16px;
}
.root :global(.en-brand) {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.7px;
  border-radius: 12px;
  transition: opacity .18s;
}
.root :global(.en-brand:hover) { opacity: .8; }
.root :global(.en-brand-accent) { color: var(--en-link); }
.root :global(.en-brand-mark) {
  display: inline-grid;
  place-items: center;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--accent), var(--accent-secondary));
  box-shadow: 0 5px 24px var(--accent-glow);
  color: white;
}
.root :global(.en-brand-mark svg) { width: 22px; height: 22px; }
.root :global(.en-nav-links) { display: flex; justify-content: flex-end; gap: 2px; }
.root :global(.en-nav-link) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 44px;
  padding: 8px 11px;
  color: var(--en-copy);
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  transition: background .18s, color .18s;
}
.root :global(.en-nav-link svg) { width: 16px; height: 16px; flex: 0 0 auto; }
.root :global(.en-nav-link:hover) { background: var(--surface-hover); color: var(--en-link); }
.root :global(.en-page) { max-width: 800px; margin: auto; padding: 16px 24px 88px; }
.root :global(.en-page-wide) { max-width: 1120px; }
.root :global(.en-language) {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: max-content;
  gap: 0;
  margin: 0 0 16px auto;
  padding: 3px;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  background: var(--surface);
  box-shadow: 0 8px 24px #00000018;
  font-size: 12px;
  font-weight: 600;
  color: var(--en-soft);
}
.root :global(.en-language > :is(a, span[aria-current])) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  padding: 8px 13px;
  border-radius: 999px;
}
.root :global(.en-language > span[aria-hidden]) { opacity: .45; }
.root :global(.en-language span[aria-current]) { background: var(--surface-hover); color: var(--foreground); }
.root :global(.en-language a:hover) { background: var(--surface); color: var(--en-link); }
.root :global(.en-page-header) {
  position: relative;
  padding: 24px 0 36px;
  margin-bottom: 36px;
  border-bottom: 1px solid var(--border-color);
}
.root :global(.en-page-header::before) {
  content: "";
  display: block;
  width: 48px;
  height: 4px;
  border-radius: 4px;
  margin-bottom: 24px;
  background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
}
.root :global(.en-page-header h1) { max-width: 750px; font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -.045em; text-wrap: balance; }
.root :global(.en-intro) { max-width: 660px; margin-top: 24px; color: var(--en-copy); font-size: 18px; line-height: 1.8; }
.root :global(.en-page-header-decorated) { padding-block: 12px 24px; margin-bottom: 24px; }
.root :global(.en-page-header-decorated::before) { display: none; }
.root :global(.en-header-decoration) { margin-bottom: 16px; }
.root :global(.en-hero) {
  padding: 40px;
  border: 1px solid var(--border-color);
  border-radius: 32px;
  background: radial-gradient(ellipse at 95% 5%, var(--accent-glow), transparent 65%), var(--surface);
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  align-items: center;
  gap: 24px;
}
.root :global(.en-hero::before) { display: none; }
.root :global(.en-hero h1) { font-size: clamp(2.75rem, 5.4vw, 4.5rem); }
.root :global(.en-hero h1::after) {
  content: "";
  display: block;
  width: 64px;
  height: 4px;
  margin-top: 24px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
}
.root :global(.en-hero-actions) { margin-top: 28px; }
.root :global(.en-copy) { color: var(--en-copy); }
.root :global(.en-copy :is(h2,h3)) { color: var(--foreground); text-wrap: balance; }
.root :global(.en-copy h2) { letter-spacing: -.025em; scroll-margin-top: 24px; }
.root :global(.en-copy a:not(.en-button)) { color: var(--en-link); text-decoration: underline; }
.root :global(.en-copy a:not(.en-button):hover) { color: var(--foreground); }
.root :global(.en-copy > :is(p, ol, ul)) { max-width: 72ch; }
.root :global(.en-copy > h2) { margin-top: 2.5em; padding-top: 8px; }
.root :global(.en-section) { margin: 48px 0; max-width: 76ch; }
.root :global(.en-halloween-card) { padding: 24px; border: 1px solid var(--border-color); border-radius: 20px; background: var(--surface); scroll-margin-top: 24px; }
.root :global(.en-section h2:first-child) { margin-top: 0; }
.root :global(.en-feature) {
  padding: 32px;
  margin: 40px 0;
  border-radius: 24px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border-color));
  background: linear-gradient(120deg, var(--surface), color-mix(in srgb, var(--accent) 8%, var(--background)));
  box-shadow: 0 16px 40px #00000020;
}
.root :global(.en-feature h2) { margin-top: 0; }
.root :global(.en-feature p:last-child) { margin-bottom: 0; }
.root :global(.en-feature p) { max-width: 72ch; }
.root :global(.en-feature .en-state-mark) { margin: 0 0 20px; }
.root :global(.en-feature-action) { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.root :global(.en-feature-action > span) { font-size: 14px; color: var(--en-soft); }
.root :global(.en-value) { padding-left: 28px; border-left: 3px solid var(--accent); }
.root :global(.en-copy > .en-catalog) { display: grid; gap: 24px; max-width: none; list-style: none; margin: 24px 0 48px; padding: 0; }
.root :global(.en-catalog li) { margin: 0; padding: 0; }
.root :global(.en-catalog-card) {
  position: relative;
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 32px;
  align-items: center;
  padding: 28px;
  border: 1px solid var(--border-color);
  border-radius: 28px;
  background: radial-gradient(ellipse at 0% 30%, var(--accent-glow), transparent 65%), var(--surface);
  transition: border-color .2s, box-shadow .2s;
}
.root :global(.en-catalog-card:has(a:hover)), .root :global(.en-catalog-card:focus-within) {
  border-color: var(--accent);
  box-shadow: 0 12px 48px var(--accent-glow);
}
.root :global(.en-catalog-card a) { font-size: 28px; font-weight: 800; letter-spacing: -.03em; }
.root :global(.en-catalog-card a::after) { content: ""; position: absolute; inset: 0; border-radius: 28px; }
.root :global(.en-catalog-card a:focus-visible::after) { outline: 2px solid var(--en-link); outline-offset: 5px; }
.root :global(.en-catalog-details) { display: grid; gap: 14px; min-width: 0; }
.root :global(.en-catalog-details h3) { margin: 0; font-size: 26px; }
.root :global(.en-catalog-details p) { margin: 0; line-height: 1.6; }
.root :global(.en-catalog-art) { position: relative; height: 240px; min-width: 0; }
.root :global(.en-catalog-art > :is(.en-card-art, .en-tod-art)) { position: absolute; top: 50%; left: 50%; margin: 0; transform: translate(-50%, -50%); }
.root :global(.en-catalog-art > .en-card-art) { width: 280px; max-width: none; transform: translate(-50%, -50%) scale(.76); }
.root :global(.en-catalog-facts) { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.root :global(.en-catalog-facts li) { margin: 0; padding: 6px 10px; border: 1px solid var(--border-color); border-radius: 10px; font-size: 13px; }
.root :global(.en-catalog-details .en-button) { width: fit-content; font-size: 14px; letter-spacing: 0; }
.root :global(.en-catalog-arrow) { display: inline-grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; margin-top: 12px; background: var(--accent-glow); color: var(--en-link); font-size: 24px; }
.root :global(.en-button) {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 24px;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  background: var(--surface-hover);
  color: var(--foreground);
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: background .18s, box-shadow .18s, border-color .18s;
}
.root :global(.en-button:hover:not(:disabled)) { border-color: var(--accent); background: var(--surface); color: var(--foreground); text-decoration: none; }
.root :global(.en-button-primary) {
  background: linear-gradient(110deg, var(--accent), var(--accent-secondary));
  color: var(--background);
  border-color: transparent;
  box-shadow: 0 6px 24px var(--accent-glow);
}
.root :global(.en-button-primary:hover:not(:disabled)) { background: linear-gradient(110deg, var(--accent-secondary), var(--accent)); color: var(--background); box-shadow: 0 8px 32px var(--accent-glow); }
.root :global(.en-button-danger) { color: #fda4af; background: transparent; border-color: #fb718540; }
.root :global(.en-button-danger:hover:not(:disabled)) { border-color: #fb7185; background: #fb718510; color: #fda4af; }
.root :global(.en-button:disabled) { opacity: .5; cursor: not-allowed; box-shadow: none; }
.root :global(.en-button-wide) { width: 100%; }
.root :global(.en-card-art) { position: relative; width: 280px; height: 300px; max-width: 100%; margin: auto; display: grid; place-items: center; }
.root :global(.en-art-orbit) { position: absolute; width: 250px; height: 250px; max-width: 100%; border: 1px solid var(--accent-glow); border-radius: 50%; box-shadow: 0 0 60px var(--accent-glow); }
.root :global(.en-art-card) { position: absolute; width: 154px; height: 216px; border-radius: 18px; border: 1px solid var(--en-link); box-shadow: 0 20px 32px #00000050; }
.root :global(.en-art-card-back) { transform: translate(-35px, 6px) rotate(-16deg); background: repeating-linear-gradient(45deg, transparent 0 10px, var(--accent-glow) 10px 11px), var(--surface-hover); display: grid; place-items: center; }
.root :global(.en-art-card-back > span) { font-size: 64px; color: var(--en-link); }
.root :global(.en-art-card-front) { transform: translate(24px, -5px) rotate(10deg); color: var(--en-link); background: linear-gradient(150deg, var(--surface-hover), var(--background)); display: grid; place-items: center; }
.root :global(.en-art-corner) { position: absolute; top: 12px; left: 14px; font-size: 25px; line-height: 1; font-weight: 800; }
.root :global(.en-art-corner span) { display: block; font-size: 16px; margin-top: 4px; }
.root :global(.en-art-corner-bottom) { top: auto; left: auto; bottom: 12px; right: 14px; transform: rotate(180deg); }
.root :global(.en-art-crown) { width: 64px; height: 64px; }
.root :global(.en-tod-mark) { display: inline-flex; align-items: center; padding: 4px; }
