  .root :global(.en-hero) { padding: 24px; border-radius: 24px; }
  .root :global(.en-intro) { font-size: 16px; }
  .root :global(.en-feature) { padding: 24px; }
  .root :global(.en-game) { padding: 20px 16px; }
  .root :global(.en-tod-panel) { gap: 18px; }
  .root :global(.en-tod-stage:not(.en-tod-choosing)) { padding: 14px; gap: 20px; }
  .root :global(.en-tod-choices) { gap: 12px; }
  .root :global(.en-tod-choice) { min-height: 152px; padding: 18px 8px; border-radius: 16px; }
  .root :global(.en-tod-symbol) { font-size: 44px; }
  .root :global(.en-tod-choice-label) { font-size: 20px; }
  .root :global(.en-card-stage) { padding: 24px 16px; }
  .root :global(.en-copy table) { font-size: 12px; }
  .root :global(.en-copy th), .root :global(.en-copy td) { padding: 12px 8px; }
  .root :global(.en-copy :is(th, td):first-child) { width: 54px; }
  .root :global(.en-copy :is(th, td):nth-child(2)) { width: 92px; }
}
@media (max-width: 480px) {
  .root :global(.en-nav-link svg) { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .root :global(*), .root :global(*::before), .root :global(*::after) { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}

/* Shared setup presentation, scoped to the two EN client islands. */
.root :global(.en-shared-setting-up) { gap: 24px 32px; }
.root :global(.en-shared-setting-up > h2) { grid-column: 1 / -1; max-width: none; width: 100%; margin: 0; padding-bottom: 20px; border-bottom: 1px solid var(--border-color); }
.root :global(.en-setup-art) { position: relative; height: 280px; min-width: 0; }
.root :global(.en-setup-art > *) { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); }
.root :global(.en-setup-panel) { display: grid; gap: 20px; min-width: 0; }
.root :global(.en-setup-panel > p) { font-size: 15px; line-height: 1.7; color: var(--en-copy); }
.root :global(.en-setup-facts) { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 0; padding: 0; list-style: none; font-size: 13px; color: var(--en-copy); }
.root :global(.en-setup-facts li) { margin: 0; padding: 0; }
.root :global(.en-setup-field) { display: grid; justify-items: start; gap: 10px; }
.root :global(.en-setup-field label) { font-size: 16px; font-weight: 700; }
.root :global(.en-setup-field select) { min-height: 48px; min-width: 96px; padding: 8px 14px; border: 1px solid var(--accent-glow); border-radius: 12px; background: var(--background); color: var(--foreground); font: inherit; font-size: 18px; cursor: pointer; }
.root :global(.en-setup-field > span) { font-size: 13px; line-height: 1.6; color: var(--en-soft); }
.root :global(.en-setup-start) { width: 100%; min-height: 56px; font-size: 16px; }
.root :global(.en-setup-panel > .en-setup-note) { font-size: 14px; line-height: 1.6; color: var(--en-soft); }
@media (max-width: 767px) {
  .root :global(.en-shared-setting-up.en-setup) { grid-template-columns: minmax(0, 1fr) 88px; gap: 18px 12px; }
  .root :global(.en-shared-setting-up > h2) { grid-column: 1; padding: 0; border: 0; line-height: 1.25; }
  .root :global(.en-setup-art) { height: 72px; }
  .root :global(.en-setup-art > *) { transform: translate(-50%, -50%) scale(.28); }
  .root :global(.en-setup-art > .en-tod-art) { transform: translate(-50%, -50%) scale(.36); }
  .root :global(.en-setup-panel) { grid-column: 1 / -1; gap: 16px; }
}

/* NHIE responds as a group: no player selector. */
.root :global(.en-nhie-game:not(.en-setup)) { max-width: 752px; margin-inline: auto; background: var(--surface); }
.root :global(.en-nhie-panel) { display: grid; gap: 18px; max-width: 640px; margin: 20px auto 0; }
.root :global(.en-nhie-panel p) { margin: 0; color: var(--en-copy); line-height: 1.6; }
.root :global(#nhie-statement) { font-size: clamp(24px, 4vw, 32px); line-height: 1.35; margin: 0; overflow-wrap: anywhere; color: #f0fdfa; }
.root :global(.en-nhie-actions) { display: flex; flex-wrap: wrap; gap: 12px; }
.root :global(.en-nhie-actions .en-button) { flex: 1 1 180px; min-height: 48px; }
.root :global(.en-nhie-session) { border-top: 1px solid var(--border-color); padding-top: 18px; }
.root :global(.en-nhie-panel .en-nhie-note), .root :global(#nhie-progress) { font-size: 14px; color: var(--en-soft); }
@media (max-width: 767px) {
 .root :global(.en-setup-art > .en-nhie-art) { transform: translate(-50%, -50%) scale(.33); }
 .root :global(.en-nhie-actions) { flex-direction: column; }
 .root :global(.en-nhie-actions .en-button) { flex: auto; width: 100%; }
}
